// Why Code: transcript horodaté et consignes de la fiche vidéo (sortie structurée Haiku).
const v = $('Webhook').first().json.body;
const mmss = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const transcript = v.segments.map((s) => `[${mmss(s.start)}] ${s.text}`).join('\n');

const SYSTEM = `Tu rédiges la fiche d'une vidéo de formation Odoo pour un consultant fonctionnel, en français, à partir de sa transcription automatique.
Règles :
- N'écris que ce que la transcription dit. N'invente aucun menu, champ ni réglage.
- Recopie les libellés d'interface et les chemins de menu en anglais, tels que prononcés (séparateur ‣, ex. Inventory ‣ Configuration ‣ Settings).
- "version" : la version d'Odoo si la vidéo la dit (« 17.0 », « 18.0 »…), sinon « indéterminée ».
- "resume" : 3 à 6 phrases sur ce que la vidéo montre.
- "quand" : dans quel besoin client cette vidéo est utile, en une ou deux phrases.
- "etapes" : chaque opération montrée, dans l'ordre, avec "debut" = la seconde où elle commence (d'après les repères [m:ss]), un titre court, le détail (champ, valeur, effet) et les menus cités.
- "pieges" : limites, prérequis ou erreurs signalés dans la vidéo ; liste vide sinon.`;
const SCHEMA = {
  type: 'object',
  properties: {
    version: { type: 'string' },
    apps: { type: 'array', items: { type: 'string' } },
    resume: { type: 'string' },
    quand: { type: 'string' },
    etapes: { type: 'array', items: { type: 'object', properties: { debut: { type: 'integer' }, titre: { type: 'string' }, detail: { type: 'string' }, menus: { type: 'array', items: { type: 'string' } } }, required: ['debut', 'titre', 'detail', 'menus'], additionalProperties: false } },
    pieges: { type: 'array', items: { type: 'string' } },
  },
  required: ['version', 'apps', 'resume', 'quand', 'etapes', 'pieges'],
  additionalProperties: false,
};

return [{
  json: {
    video: v,
    claudeBody: {
      model: 'claude-haiku-5-5',
      max_tokens: 12000,
      output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
      system: SYSTEM,
      messages: [{ role: 'user', content: `Vidéo « ${v.title} » (cours « ${v.course} »${v.section && v.section !== v.course ? ` › ${v.section}` : ''}).\n\nTranscription :\n${transcript}` }],
    },
  },
}];

// Why Code: fiche + passages de transcription au format de la bibliothèque, et lot d'embeddings (préfixe document de gemini-embedding-2).
const { video: v } = $('Build summary request').first().json;
const raw = ($json.content ?? []).find((c) => c.type === 'text')?.text ?? '';
let f;
try { f = JSON.parse(raw); } catch (e) { throw new Error(`Fiche illisible pour ${v.id} : ${raw.slice(0, 200)}`); }

const mmss = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const url = `https://www.youtube.com/watch?v=${v.id}`;
const module = v.course.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/^odoo academy - /, '').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const head = `Vidéo officielle Odoo « ${v.title} » (cours « ${v.course} »${v.section && v.section !== v.course ? ` › ${v.section}` : ''}), langue ${v.language}. Transcription automatique YouTube, non relue. Version : ${f.version}.`;

// Fiche : en-tête, résumé, étapes horodatées, pièges ; coupée en morceaux de 2 400 caractères au plus.
const lines = [
  head,
  `Applications : ${f.apps.join(', ') || 'non précisées'}.`,
  `Quand l'utiliser : ${f.quand}`,
  `Résumé : ${f.resume}`,
  ...f.etapes.map((e) => `- [${mmss(e.debut)}] **${e.titre}** : ${e.detail}${e.menus.length ? ` Menus : ${e.menus.join(' ; ')}.` : ''}`),
  ...(f.pieges.length ? [`Pièges : ${f.pieges.join(' ')}`] : []),
];
const fiche = [];
for (const l of lines) {
  if (fiche.length && fiche[fiche.length - 1].length + l.length < 2400) fiche[fiche.length - 1] += `\n${l}`;
  else fiche.push(l);
}
const chunks = fiche.map((content, k) => ({ breadcrumb: `Vidéo « ${v.title} » > Fiche${k ? ` (suite ${k + 1})` : ''}`, url, content, start_s: null, end_s: null }));
// Passages de transcription (fenêtres de 2 minutes préparées par le script local).
for (const s of v.segments) {
  chunks.push({ breadcrumb: `Vidéo « ${v.title} » > Transcription (${mmss(s.start)}–${mmss(s.end)})`, url: `${url}&t=${Math.floor(s.start)}s`, content: `${head}\nTranscription : ${s.text}`, start_s: Math.floor(s.start), end_s: Math.ceil(s.end) });
}
chunks.forEach((c, k) => Object.assign(c, { ordinal: k, module, tokens: Math.ceil(c.content.length / 4) }));

const u = $json.usage ?? {};
const usd = ((u.input_tokens ?? 0) * 0.1 + (u.output_tokens ?? 0) * 0.5) / 1e6;
return [{
  json: {
    source: { title: v.title, url, path: `youtube/${v.id}`, module },
    chunks,
    usd,
    embedBody: { requests: chunks.map((c) => ({ model: 'models/gemini-embedding-2', content: { parts: [{ text: `title: ${c.breadcrumb} | text: ${c.content}` }] }, outputDimensionality: 1536 })) },
  },
}];

// Why Code: assemble les passages et leurs vecteurs en un seul paramètre JSON pour l'insertion.
// Fiche Haiku (transcript fourni) ou analyse Gemini de la vidéo.
const b = ($('Build chunks').isExecuted ? $('Build chunks') : $('Build chunks (video)')).first().json;
const vectors = $json.embeddings.map((e) => `[${e.values.join(',')}]`);
return [{ json: { usd: b.usd, chunks: b.chunks.length, payload: JSON.stringify({ ...b.source, chunks: b.chunks.map((c, k) => ({ ...c, embedding: vectors[k] })) }) } }];

// Why Code: consignes et schéma de l'analyse vidéo par Gemini (lecture de la vidéo YouTube côté Google, aucun transcript à fournir).
const v = $('Webhook').first().json.body;
const SYSTEM = `Tu analyses une vidéo officielle de la chaîne YouTube d'Odoo pour la base de connaissances d'un consultant fonctionnel Odoo. Tu rapportes fidèlement ce qui est dit et montré, sans rien ajouter de ta propre connaissance d'Odoo. Réponds uniquement en JSON.`;
const PROMPT = `Vidéo : « ${v.title} », cours « ${v.course} »${v.section && v.section !== v.course ? ` › ${v.section}` : ''}.

Produis :
- "language" : code de la langue parlée (en, fr, it…) ;
- "odooVersion" : "value" = la version d'Odoo présentée (« 17.0 », « 18.0 », « 19.0 »…) seulement si la vidéo la dit, l'affiche, ou si le titre la donne ; sinon « indéterminée ». "evidence" = l'indice exact ;
- "apps" : applications Odoo traitées, avec leur nom anglais d'interface (Helpdesk, Accounting, Inventory…) ;
- "summary" : résumé en français, 3 à 6 phrases ;
- "segments" : la vidéo entière découpée en segments de 1 à 3 minutes qui se suivent sans trou, avec "start" et "end" en secondes depuis le début, un "title" court en français, "transcript" = transcription fidèle et complète de ce qui est dit, dans la langue d'origine (pas de résumé), et "onScreen" = en français, ce qui est montré : écrans, menus et chemins de menu (séparateur ‣, libellés tels qu'affichés), boutons, champs et valeurs saisies ;
- "features" : chaque fonctionnalité présentée : "app", "name" (libellé anglais tel qu'affiché ou prononcé), "description" en français (ce qu'elle fait, comment l'activer ou l'utiliser, d'après la vidéo), "menuPaths" (chemins de menu vus ou cités, sinon liste vide), "start" (seconde où elle est présentée) ;
- "cautions" : mises en garde, limites, prérequis ou conseils donnés dans la vidéo (édition Enterprise, application à installer, paramètre à activer…), en français, avec "start".
N'invente rien : un menu ou un libellé non visible ni prononcé n'est pas cité.`;
const int = { type: 'integer', minimum: 0 };
const SCHEMA = {
  type: 'object',
  properties: {
    language: { type: 'string' },
    odooVersion: { type: 'object', properties: { value: { type: 'string' }, evidence: { type: 'string' } }, required: ['value', 'evidence'] },
    apps: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
    segments: { type: 'array', items: { type: 'object', properties: { start: int, end: int, title: { type: 'string' }, transcript: { type: 'string' }, onScreen: { type: 'string' } }, required: ['start', 'end', 'title', 'transcript', 'onScreen'] } },
    features: { type: 'array', items: { type: 'object', properties: { app: { type: 'string' }, name: { type: 'string' }, description: { type: 'string' }, menuPaths: { type: 'array', items: { type: 'string' } }, start: int }, required: ['app', 'name', 'description', 'menuPaths', 'start'] } },
    cautions: { type: 'array', items: { type: 'object', properties: { text: { type: 'string' }, start: int }, required: ['text', 'start'] } },
  },
  required: ['language', 'odooVersion', 'apps', 'summary', 'segments', 'features', 'cautions'],
};
return [{
  json: {
    video: v,
    geminiBody: {
      systemInstruction: { parts: [{ text: SYSTEM }] },
      // Une image toutes les 2 secondes en basse résolution : menus lisibles, coût par seconde réduit.
      contents: [{ role: 'user', parts: [{ fileData: { fileUri: `https://www.youtube.com/watch?v=${v.id}` }, videoMetadata: { fps: 0.5 } }, { text: PROMPT }] }],
      generationConfig: { responseMimeType: 'application/json', responseJsonSchema: SCHEMA, mediaResolution: 'MEDIA_RESOLUTION_LOW', thinkingConfig: { thinkingLevel: 'LOW' }, maxOutputTokens: 60000 },
    },
  },
}];

// Why Code: fiche (fonctionnalités, mises en garde) et passages horodatés (à l'écran + transcription) au format des vidéos déjà en base, puis lot d'embeddings.
const { video: v } = $('Build video request (Gemini)').first().json;
const raw = ($json.candidates?.[0]?.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? '').join('');
let a;
try { a = JSON.parse(raw); } catch (e) { throw new Error(`Analyse illisible pour ${v.id} (${$json.candidates?.[0]?.finishReason ?? 'sans réponse'}) : ${raw.slice(0, 200)}`); }

const mmss = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const url = `https://www.youtube.com/watch?v=${v.id}`;
const module = v.course.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '').replace(/^odoo academy - /, '').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const head = `Vidéo officielle Odoo « ${v.title} » (cours « ${v.course} »${v.section && v.section !== v.course ? ` › ${v.section}` : ''}), langue ${a.language}. Transcription générée par IA, non relue.`;

const lines = [
  head,
  `Applications : ${a.apps.join(', ') || 'non précisées'}. Version : ${a.odooVersion.value}${a.odooVersion.value === 'indéterminée' ? '' : ` (${a.odooVersion.evidence})`}.`,
  `Résumé : ${a.summary}`,
  ...a.features.map((f) => `- [${mmss(f.start)}] **${f.name}** (${f.app}) : ${f.description}${f.menuPaths.length ? ` Menus : ${f.menuPaths.join(' ; ')}.` : ''}`),
  ...a.cautions.map((c) => `- Attention [${mmss(c.start)}] : ${c.text}`),
];
const fiche = [];
for (const l of lines) {
  if (fiche.length && fiche[fiche.length - 1].length + l.length < 2400) fiche[fiche.length - 1] += `\n${l}`;
  else fiche.push(l);
}
const chunks = fiche.map((content, k) => ({ breadcrumb: `Vidéo « ${v.title} » > Fiche${k ? ` (suite ${k + 1})` : ''}`, url, content, start_s: null, end_s: null }));
for (const s of a.segments) {
  chunks.push({ breadcrumb: `Vidéo « ${v.title} » > ${s.title} (${mmss(s.start)}–${mmss(s.end)})`, url: `${url}&t=${s.start}s`, content: `${head}\nÀ l'écran : ${s.onScreen}\nTranscription : ${s.transcript}`, start_s: s.start, end_s: s.end });
}
chunks.forEach((c, k) => Object.assign(c, { ordinal: k, module, tokens: Math.ceil(c.content.length / 4) }));

// gemini-3.8-flash : 0,75 USD par million en entrée (vidéo comprise), 3,75 en sortie et réflexion (passe à 1,50 / 7,50 le 01/01/2027).
const u = $json.usageMetadata ?? {};
const usd = ((u.promptTokenCount ?? 0) * 0.75 + ((u.candidatesTokenCount ?? 0) + (u.thoughtsTokenCount ?? 0)) * 3.75) / 1e6;
return [{
  json: {
    source: { title: v.title, url, path: `youtube/${v.id}`, module },
    chunks,
    usd,
    embedBody: { requests: chunks.map((c) => ({ model: 'models/gemini-embedding-2', content: { parts: [{ text: `title: ${c.breadcrumb} | text: ${c.content}` }] }, outputDimensionality: 1536 })) },
  },
}];
